insert into public.idea_nodes(id,tree_id,parent_id,author_id,title,content,node_type,status,metadata,created_at) values('20000000-0000-4000-8000-000000000006','10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000002','00000000-0000-4000-8000-000000000002','Solar-powered community water monitor','Combine the sensor and solar module into a locally repairable monitoring station. A steward checks calibration weekly, and an offline log preserves readings until a connection is available. Pilot one station before expanding.','synthesis','published','{"sources":["20000000-0000-4000-8000-000000000002","20000000-0000-4000-8000-000000000003"],"model":"sample-blueprint","blueprint":{"title":"Solar-powered community water monitor","concept":"Combine the sensor and solar module into a locally repairable monitoring station. A steward checks calibration weekly, and an offline log preserves readings until a connection is available. Pilot one station before expanding.","problem_statement":"Clean water starts with clear information. An affordable, community-owned way to understand what’s in our water.","proposed_mechanism":"Integrate both technical branches with a named local steward, a documented maintenance process, and an offline operating mode.","key_components":["Low-power turbidity sensor","A little sunlight goes a long way","Let communities own the data"],"complementary_strengths":["Infrastructure independence","Local repair and ownership"],"conflicts_and_constraints":["Energy and maintenance budgets need field measurements.","A named steward must own routine checks."],"risks_or_open_questions":["What fails first in a four-week pilot?","Can repairs use locally available parts?"],"suggested_next_contribution":"Publish a pilot protocol with a bill of materials and measurable success criteria."}}'::jsonb,'2026-10-22T10:00:00Z') on conflict(id) do nothing;
