insert into public.idea_nodes(id,tree_id,parent_id,author_id,title,content,node_type,status,metadata,created_at) values('40000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000003',null,'00000000-0000-4000-8000-000000000001','An offline lifeline in a crisis','When cell towers fail, neighborhoods need to coordinate requests and supplies. Build a documented kit with offline messaging, local power, and a clear operating procedure for trained volunteers.','root','published','{}'::jsonb,'2026-10-18T10:00:00Z') on conflict(id) do nothing;
