insert into public.idea_nodes(id,tree_id,parent_id,author_id,title,content,node_type,status,metadata,created_at) values('40000000-0000-4000-8000-000000000006','10000000-0000-4000-8000-000000000003','40000000-0000-4000-8000-000000000002','00000000-0000-4000-8000-000000000002','A resilient community response hub','Combine mesh communication, solar charging, and a minimal supply ledger. Volunteers exchange verified requests without internet access and reconcile inventories when hubs reconnect. Validate the kit in a community drill.','synthesis','published','{"sources":["40000000-0000-4000-8000-000000000002","40000000-0000-4000-8000-000000000003"],"model":"sample-blueprint","blueprint":{"title":"A resilient community response hub","concept":"Combine mesh communication, solar charging, and a minimal supply ledger. Volunteers exchange verified requests without internet access and reconcile inventories when hubs reconnect. Validate the kit in a community drill.","problem_statement":"Communication and essential supplies when infrastructure goes down. Built openly, ready for the field.","proposed_mechanism":"Integrate both technical branches with a named local steward, a documented maintenance process, and an offline operating mode.","key_components":["Mesh networks without cell towers","Solar charging at every hub","Track essential medical supplies"],"complementary_strengths":["Infrastructure independence","Local repair and ownership"],"conflicts_and_constraints":["Energy and maintenance budgets need field measurements.","A named steward must own routine checks."],"risks_or_open_questions":["What fails first in a four-week pilot?","Can repairs use locally available parts?"],"suggested_next_contribution":"Publish a pilot protocol with a bill of materials and measurable success criteria."}}'::jsonb,'2026-10-22T10:00:00Z') on conflict(id) do nothing;
